async function recordStaffActivity(action,details){if(role!=='staff'||!user)return;const r=await db.rpc('record_staff_activity',{p_action:String(action||'Activity').slice(0,120),p_details:String(details||'').slice(0,2000)});if(r.error)console.warn('Activity log:',r.error.message)}
function message(text){$('#loginMessage').textContent=text||''}
function can(id){if(role==='admin')return true;if(role!=='staff')return false;if(id==='dashboard')return true;const aliases={qr_menu_images:'qr_menu',discount:'discounts'};const key=aliases[id]||id;return permissions[id]===true||permissions[key]===true||(Array.isArray(permissions)&&(permissions.includes(id)||permissions.includes(key)))}
function setLang(v){lang=v;document.documentElement.lang=v;document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));if(user)render(current)}
function closeMobileNav(){const sidebar=$('#sidebar'),button=$('#menuButton');sidebar.classList.remove('open');$('#sidebarBackdrop').classList.remove('visible');button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','Open navigation menu')}
function showLogin(){$('#appView').hidden=true;$('#loginView').hidden=false}
function showApp(){$('#loginView').hidden=true;$('#appView').hidden=false;$('#userLabel').textContent=(role==='admin'?'SUPER ADMIN · ':'STAFF · ')+(user.email||'');buildNav();render('dashboard')}
async function authorize(u){user=u;role='guest';permissions={};if(cfg.ADMIN_USER_ID&&u.id===cfg.ADMIN_USER_ID){role='admin';return}
const a=await db.from('admin_users').select('user_id').eq('user_id',u.id).maybeSingle();if(a.error)throw a.error;if(a.data){role='admin';return}
const s=await db.from('staff').select('permissions,is_active').eq('auth_user_id',u.id).maybeSingle();if(s.error)throw s.error;if(!s.data||s.data.is_active!==true)throw new Error(t('denied'));role='staff';permissions=s.data.permissions||{}}
function buildNav(){$('#navigation').innerHTML='<div class="nav-heading">GESTIONE</div>'+modules.filter(([id])=>can(id)).map(([id,ico])=>'<button class="nav-link '+(id===current?'active':'')+'" data-module="'+id+'"><span>'+ico+'</span>'+t(labels[id]||id)+'</button>').join('')}
function stat(title,value){return '<article class="stat"><small>'+title+'</small><strong>'+value+'</strong></article>'}
async function count(table){const r=await db.from(table).select('*',{count:'exact',head:true});return r.error?'—':r.count??0}
async function dashboard(){const items=[['website_analytics','visits'],['menu_items','dishes'],['bookings','bookings'],['reviews','reviews']];const values=await Promise.all(items.map(x=>count(x[0])));const pending=await db.from('bookings').select('*',{count:'exact',head:true}).eq('status','pending');const cards=modules.filter(([id])=>id!=='dashboard'&&can(id)).map(([id,ico])=>'<button class="module-card" data-module="'+id+'"><b>'+ico+' '+t(labels[id]||id)+'</b><span>'+t('secure')+'</span></button>').join('');return '<section class="hero"><div><p class="eyebrow">♛ NABABI RISTORANTE</p><h2>'+t('welcomeBack')+'</h2><p>'+t('secure')+'</p></div><div class="hero-mark">♛</div></section><div class="stats">'+items.map((x,i)=>stat(t(x[1]),values[i])).join('')+stat(t('newBookings'),pending.error?'—':pending.count||0)+'</div><section class="panel"><h2>'+t('modules')+'</h2><div class="module-grid">'+cards+'</div></section>'}
function field(label,name,type='text',extra=''){return '<label class="field">'+label+'<input name="'+name+'" type="'+type+'" '+extra+'></label>'}
function selectField(label,name,options){return '<label class="field">'+label+'<select name="'+name+'">'+options+'</select></label>'}
async function menuPage(){const [cats,dishes]=await Promise.all([db.from('categories').select('id,name').order('name'),db.from('menu_items').select('*').order('name').limit(250)]);if(cats.error)throw cats.error;if(dishes.error)throw dishes.error;const catOptions=(cats.data||[]).map(c=>'<option value="'+esc(c.name)+'">'+esc(c.name)+'</option>').join('');return '<section class="panel"><h2 id="dishHeading">'+(editingDish?'Edit dish':'Add menu item')+'</h2><form id="dishForm" class="admin-form">'+field(t('name'),'name','text','required maxlength="150"')+field(t('price'),'price','number','required min="0" step="0.01"')+selectField(t('category'),'category','<option value="">Select category</option>'+catOptions)+ '<label class="field">'+t('description')+'<textarea name="description" maxlength="1000"></textarea></label>'+field('Dish image','image','file','accept="image/jpeg,image/png,image/webp"')+'<div class="dish-image-preview-wrap" id="dishImagePreviewWrap" hidden><img id="dishImagePreview" alt="Dish image preview"></div>'+selectField(t('available'),'is_available','<option value="true">Yes</option><option value="false">No</option>')+'<div class="form-actions"><button class="gold-button" type="submit">'+t('save')+'</button><button id="cancelDish" class="secondary-button" type="button">'+t('cancel')+'</button></div><p id="dishStatus" class="message"></p></form></section><section class="panel"><h2>Saved dishes</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Image</th><th>Name</th><th>Category</th><th>Price</th><th>Available</th><th>Actions</th></tr></thead><tbody>'+(dishes.data||[]).map(d=>'<tr><td>'+(d.image_url?'<img class="dish-thumb" src="'+esc(d.image_url)+'" alt="'+esc(d.name)+'" loading="lazy">':'<span class="dish-thumb-placeholder">—</span>')+'</td><td>'+esc(d.name)+'</td><td>'+esc(d.category)+'</td><td>€'+esc(d.price)+'</td><td>'+String(!!d.is_available)+'</td><td><button class="small-button" data-edit-dish="'+esc(d.id)+'">Edit</button> <button class="small-button danger-button" data-delete-dish="'+esc(d.id)+'">Delete</button></td></tr>').join('')+'</tbody></table></div></section>'}
function storageUploadError(err,bucket){
 const raw=String(err?.message||err||'Upload failed.');
 if(/failed to fetch|networkerror|load failed|fetch failed/i.test(raw)){
  return 'Supabase Storage could not be reached (Failed to fetch). Check the device internet connection, then verify that the Supabase project URL and Storage bucket "'+bucket+'" are correct and that the project is online. This is a network/request failure, not proof that the image was saved.';
 }
 return raw;
}
async function uploadImage(file,folder,maxBytes=8*1024*1024){
 if(!file||!file.size)return null;
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>maxBytes)throw new Error('Use JPG, PNG or WebP, maximum '+Math.round(maxBytes/1024/1024)+' MB.');
 if(!db)throw new Error('Database connection is not ready. Reload the page and sign in again.');
 const bucket=String(cfg.STORAGE_BUCKET||'nababi-media').trim();
 if(!cfg.SUPABASE_URL||!/^https:\/\//i.test(cfg.SUPABASE_URL))throw new Error('Supabase project URL is missing or invalid. Check the Admin V2 configuration.');
 const ext=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg';
 const path=folder+'/'+Date.now()+'-'+(crypto.randomUUID?.()||Math.random().toString(36).slice(2))+'.'+ext;
 let up;
 try{up=await db.storage.from(bucket).upload(path,file,{cacheControl:'3600',upsert:false,contentType:file.type})}
 catch(err){throw new Error(storageUploadError(err,bucket))}
 if(up.error)throw new Error(storageUploadError(up.error,bucket));
 const publicUrl=db.storage.from(bucket).getPublicUrl(up.data.path).data.publicUrl;
 if(!publicUrl)throw new Error('The image was uploaded, but Supabase did not return a public image URL. Check the bucket visibility and configuration.');
 return publicUrl;
}
async function saveDish(e){e.preventDefault();const f=e.target,fd=new FormData(f),status=$('#dishStatus');const b=f.querySelector('[type=submit]');b.disabled=true;try{const payload={name:String(fd.get('name')||'').trim(),price:Number(fd.get('price')),category:String(fd.get('category')||''),description:String(fd.get('description')||'').trim()||null,is_available:fd.get('is_available')==='true'};if(!payload.name||!payload.category||!Number.isFinite(payload.price)||payload.price<0)throw new Error('Enter a name, category and valid price.');const image=await uploadImage(fd.get('image'),'menu');if(image)payload.image_url=image;const q=editingDish?db.from('menu_items').update(payload).eq('id',editingDish):db.from('menu_items').insert(payload);const r=await q;if(r.error)throw r.error;await recordStaffActivity(editingDish?'Updated':'Created','Module: Menu Manager — '+payload.name);editingDish=null;await render('menu_manager')}catch(err){status.textContent=err.message}finally{b.disabled=false}}
async function categoriesPage(){const r=await db.from('categories').select('*').order('name');if(r.error)throw r.error;return '<section class="panel"><h2>Add category</h2><form id="categoryForm" class="admin-form">'+field(t('name'),'name','text','required maxlength="100"')+'<button class="gold-button">'+t('save')+'</button><p id="categoryStatus" class="message"></p></form></section><section class="panel"><h2>Categories</h2>'+(r.data||[]).map(c=>'<div class="record-row"><b>'+esc(c.name)+'</b><button class="small-button danger-button" data-delete-category="'+esc(c.id)+'">Delete</button></div>').join('')+'</section>'}
async function saveCategory(e){e.preventDefault();const name=String(new FormData(e.target).get('name')||'').trim();if(!name)return;const r=await db.from('categories').insert({name});if(r.error)$('#categoryStatus').textContent=r.error.message;else{await recordStaffActivity('Created','Module: Categories — '+name);await render('categories')}}
async function gamesPage(){const r=await db.from('nababi_games').select('game_key,title,image_url,is_enabled,updated_at').order('game_key');if(r.error)throw r.error;const rows=r.data||[];return '<section class="panel"><h2>'+(editingGame?'Edit game':'Add game')+'</h2><form id="gameForm" class="admin-form">'+selectField(t('gameKey'),'game_key',allowedGames.map(k=>'<option value="'+k+'">'+k+'</option>').join(''))+field(t('name'),'title','text','required maxlength="100"')+field(t('imageUrl'),'image_url','url','placeholder="https://…"')+selectField(t('enabled'),'is_enabled','<option value="true">Enabled</option><option value="false">Disabled</option>')+'<div class="form-actions"><button class="gold-button">'+t('save')+'</button><button id="cancelGame" class="secondary-button" type="button">'+t('cancel')+'</button></div><p id="gameStatus" class="message"></p></form></section><section class="panel"><h2>Games list</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Game</th><th>Title</th><th>Status</th><th>Actions</th></tr></thead><tbody>'+rows.map(g=>'<tr><td>'+esc(g.game_key)+'</td><td>'+esc(g.title)+'</td><td>'+ (g.is_enabled?'Enabled':'Disabled')+'</td><td><button class="small-button" data-edit-game="'+esc(g.game_key)+'">Edit</button> <button class="small-button danger-button" data-delete-game="'+esc(g.game_key)+'">Delete</button></td></tr>').join('')+'</tbody></table></div><p class="help">The database permits only the five predefined game keys. Deleted predefined games can be added again.</p></section>'}
async function staffPage(){const r=await db.from('staff').select('id,full_name,email,phone,photo_url,auth_user_id,permissions,is_active').order('full_name');if(r.error)throw r.error;const permissionBoxes=modules.filter(([id])=>id!=='dashboard').map(([id])=>'<label class="check-label"><input type="checkbox" name="perm" value="'+id+'"> '+t(labels[id]||id)+'</label>').join('');return '<section class="panel"><h2>Create Full Staff Account</h2><p class="help">The password is sent only to the protected Supabase Edge Function; it is not stored in this page or in a public table.</p><form id="staffForm" class="admin-form">'+field(t('staffName'),'full_name','text','required maxlength="120"')+field(t('email'),'email','email','required maxlength="254"')+field(t('phone'),'phone','tel','maxlength="40"')+field(t('password'),'password','password','required minlength="10" autocomplete="new-password"')+'<div><b>'+t('permissions')+'</b><div class="permission-grid">'+permissionBoxes+'</div></div><button class="gold-button" type="submit">Create staff account</button><p id="staffStatus" class="message"></p></form></section><section class="panel"><h2>Attendance-only Staff Account</h2><p class="help">Create a profile for the shared Staff QR check-in page.</p><form id="attendanceStaffForm" class="admin-form">'+field(t('staffName'),'full_name','text','required maxlength="120"')+field('Staff photo','photo','file','accept="image/jpeg,image/png,image/webp" required')+field('Personal PIN (4 digits)','pin','password','inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" required')+'<button class="gold-button" type="submit">Create attendance account</button><p id="attendanceStaffStatus" class="message"></p></form></section><section class="panel"><h2>Staff Check-in Announcements</h2><form id="staffAnnouncementForm" class="admin-form">'+field('Title','title','text','required maxlength="180"')+'<label class="field">Message<textarea name="message" required maxlength="2000"></textarea></label>'+field('Starts at','starts_at','datetime')+field('Ends at','ends_at','datetime')+'<button class="gold-button" type="submit">Publish announcement</button><p id="staffAnnouncementStatus" class="message"></p></form><div id="staffAnnouncementList"></div></section><section class="panel"><h2>Staff accounts</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Email</th><th>Type</th><th>Status</th><th>Actions</th></tr></thead><tbody>'+(r.data||[]).map(s=>'<tr><td>'+esc(s.full_name)+'</td><td>'+esc(s.email)+'</td><td>'+(s.auth_user_id?'Email login':'Attendance only')+'</td><td>'+(s.is_active?'Active':'Disabled')+'</td><td><button class="small-button" data-edit-staff="'+esc(s.id)+'">Permissions</button> <button class="small-button" data-toggle-staff="'+esc(s.id)+'" data-active="'+String(!!s.is_active)+'">'+(s.is_active?'Disable':'Enable')+'</button> <button class="small-button danger-button" data-delete-staff="'+esc(s.id)+'">Remove</button></td></tr>').join('')+'</tbody></table></div><p class="help">Staff account creation and removal use protected Edge Functions. PIN account creation uses the existing protected database function.</p></section>'}
async function createStaff(e){e.preventDefault();if(role!=='admin')throw new Error('Only Super Admin can create staff.');const f=e.target,fd=new FormData(f),status=$('#staffStatus'),permissions={};modules.filter(([id])=>id!=='dashboard').forEach(([id])=>permissions[id]=false);f.querySelectorAll('[name=perm]:checked').forEach(x=>permissions[x.value]=true);const button=f.querySelector('[type=submit]');button.disabled=true;try{const {data,error}=await db.functions.invoke('create-staff-account',{body:{full_name:String(fd.get('full_name')).trim(),email:String(fd.get('email')).trim().toLowerCase(),phone:String(fd.get('phone')||'').trim(),password:String(fd.get('password')),permissions}});if(error)throw error;if(data?.error)throw new Error(data.error);if(!data?.success)throw new Error('Staff account creation was not confirmed.');await render('staff')}catch(err){status.textContent=err.message}finally{button.disabled=false}}
