function inputFor(field,value=''){
 const [name,label,type,requiredOrOptions]=field;
 const required=requiredOrOptions===true;
 const options=Array.isArray(requiredOrOptions)?requiredOrOptions:null;
 const safe=esc(value??'');
 if(type==='image')return '<label class="field">'+label+'<input name="'+name+'" type="file" accept="image/jpeg,image/png,image/webp"><input type="hidden" name="'+name+'_existing" value="'+safe+'">'+(value?'<img class="crud-image-preview" src="'+safe+'" alt="Current image">':'')+'</label>';
 if(type==='boolean')return '<label class="check-label"><input type="checkbox" name="'+name+'" '+(value===true?'checked':'')+'> '+label+'</label>';
 if(type==='textarea')return '<label class="field">'+label+'<textarea name="'+name+'" '+(required?'required':'')+'>'+safe+'</textarea></label>';
 if(type==='select')return '<label class="field">'+label+'<select name="'+name+'">'+(options||[]).map(v=>'<option value="'+esc(v)+'" '+(String(value)===v?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label>';
 let v=safe;
 if(type==='datetime'&&value){const d=new Date(value);if(!Number.isNaN(d.getTime()))v=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
 const inputType=type==='datetime'?'datetime-local':type;
 return '<label class="field">'+label+'<input name="'+name+'" type="'+inputType+'" value="'+v+'" '+(required?'required':'')+(type==='number'?' step="any"':'')+'></label>';
}
function displayValue(v){if(v===null||v===undefined||v==='')return '—';if(typeof v==='boolean')return v?'Yes':'No';if(typeof v==='object')return esc(JSON.stringify(v));return esc(v)}
function breakingNewsMediaCell(row){
 const image=row.image_url?'<div class="news-media-item"><span class="news-media-type">IMAGE</span><img class="news-media-thumb" src="'+esc(row.image_url)+'" alt="Breaking News image" loading="lazy"></div>':'';
 const videoUrl=String(row.youtube_url||'').trim();
 let videoId='';
 try{const u=new URL(videoUrl);videoId=u.searchParams.get('v')||u.pathname.split('/').filter(Boolean).pop()||'';if(!/^[A-Za-z0-9_-]{11}$/.test(videoId))videoId=''}catch(_){}
 const video=videoUrl?'<div class="news-media-item"><span class="news-media-type video">VIDEO</span>'+(videoId?'<a href="https://www.youtube.com/watch?v='+videoId+'" target="_blank" rel="noopener noreferrer"><img class="news-media-thumb" src="https://img.youtube.com/vi/'+videoId+'/hqdefault.jpg" alt="YouTube video thumbnail" loading="lazy"></a>':'<span class="news-video-link">Video URL saved</span>')+'<a class="news-media-open" href="'+esc(videoUrl)+'" target="_blank" rel="noopener noreferrer">Open video ↗</a></div>':'';
 return image||video?'<div class="news-media-preview">'+image+video+'</div>':'<span class="news-media-none">No media</span>';
}

function attendanceDateValue(d){const x=new Date(d);return [x.getFullYear(),String(x.getMonth()+1).padStart(2,'0'),String(x.getDate()).padStart(2,'0')].join('-')}
function attendanceDuration(a,b){if(!a||!b)return null;const toMin=v=>{const p=String(v).slice(0,5).split(':').map(Number);return p.length===2&&p.every(Number.isFinite)?p[0]*60+p[1]:null};let x=toMin(a),y=toMin(b);if(x===null||y===null)return null;if(y<x)y+=1440;return y-x}
function attendanceHours(min){if(min===null)return '—';return Math.floor(min/60)+'h '+String(min%60).padStart(2,'0')+'m'}
async function attendancePage(){
 const today=new Date(),endDefault=attendanceDateValue(today),startDefault=attendanceDateValue(new Date(today.getFullYear(),today.getMonth(),today.getDate()-6));
 const start=attendanceStart||startDefault,end=attendanceEnd||endDefault;
 if(start>end)throw new Error('Start date must be before end date.');
 const [a,s]=await Promise.all([
  db.from('staff_attendance').select('staff_name,attendance_date,check_in,check_out,status').gte('attendance_date',start).lte('attendance_date',end).order('attendance_date',{ascending:false}).order('check_in',{ascending:false}).limit(1000),
  db.from('staff').select('full_name,photo_url')
 ]);
 if(a.error)throw a.error;if(s.error)throw s.error;
 attendanceRows=a.data||[];
 const photos={};(s.data||[]).forEach(x=>{if(x.full_name)photos[x.full_name]=x.photo_url||''});
 const names=[...new Set(attendanceRows.map(x=>x.staff_name||'Unknown staff'))];
 const complete=attendanceRows.filter(x=>x.check_in&&x.check_out);
 const missing=attendanceRows.filter(x=>x.check_in&&!x.check_out);
 const totalMinutes=complete.reduce((sum,x)=>sum+(attendanceDuration(x.check_in,x.check_out)||0),0);
 const statusCounts={};attendanceRows.forEach(x=>{const k=String(x.status||'Unknown');statusCounts[k]=(statusCounts[k]||0)+1});
 const rows=attendanceRows.map(x=>{const name=x.staff_name||'Unknown staff',duration=attendanceDuration(x.check_in,x.check_out);return '<tr><td><button class="attendance-person attendance-person-button" type="button" data-attendance-staff="'+esc(name)+'">'+(photos[name]?'<img src="'+esc(photos[name])+'" alt="">':'<span class="attendance-avatar">'+esc(name.slice(0,1).toUpperCase())+'</span>')+'<b>'+esc(name)+'</b></button></td><td>'+esc(x.attendance_date||'—')+'</td><td>'+esc(x.check_in||'—')+'</td><td>'+esc(x.check_out||'—')+'</td><td>'+attendanceHours(duration)+'</td><td><span class="attendance-status">'+esc(x.status||'Unknown')+'</span></td></tr>'}).join('');
 const personRows=selectedAttendanceStaff?attendanceRows.filter(x=>(x.staff_name||'Unknown staff')===selectedAttendanceStaff):[];
 const personComplete=personRows.filter(x=>x.check_in&&x.check_out),personMissing=personRows.filter(x=>x.check_in&&!x.check_out);
 const personMinutes=personComplete.reduce((sum,x)=>sum+(attendanceDuration(x.check_in,x.check_out)||0),0);
 const personHtml=selectedAttendanceStaff?'<section class="panel attendance-person-report"><div class="attendance-section-head"><div><p class="eyebrow">INDIVIDUAL STAFF REPORT</p><h2>'+esc(selectedAttendanceStaff)+'</h2><p class="help">'+esc(start)+' — '+esc(end)+' · '+personRows.length+' records</p></div><div class="attendance-actions"><button class="secondary-button" id="exportIndividualAttendanceCsv" type="button">Download this Staff CSV</button><button class="secondary-button" id="printIndividualAttendance" type="button">Print this Staff</button><button class="secondary-button" id="closeIndividualAttendance" type="button">Close</button></div></div><div class="stats attendance-stats"><article class="stat"><small>Attendance records</small><strong>'+personRows.length+'</strong></article><article class="stat"><small>Complete shifts</small><strong>'+personComplete.length+'</strong></article><article class="stat"><small>Missing checkout</small><strong>'+personMissing.length+'</strong></article><article class="stat"><small>Recorded work time</small><strong>'+attendanceHours(personMinutes)+'</strong></article></div>'+(personRows.length?'<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Check in</th><th>Check out</th><th>Work time</th><th>Status</th></tr></thead><tbody>'+personRows.map(x=>'<tr><td>'+esc(x.attendance_date||'—')+'</td><td>'+esc(x.check_in||'—')+'</td><td>'+esc(x.check_out||'—')+'</td><td>'+attendanceHours(attendanceDuration(x.check_in,x.check_out))+'</td><td>'+esc(x.status||'Unknown')+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty">No records for this Staff in the selected date range.</div>')+'</section>':'';

 const statusLine=Object.entries(statusCounts).map(([k,v])=>'<span class="attendance-chip">'+esc(k)+': <b>'+v+'</b></span>').join('');
 return '<section class="attendance-hero"><div><p class="eyebrow">NABABI · TEAM MANAGEMENT</p><h2>Staff Attendance</h2><p>Review check-in, check-out and recorded working time.</p></div><div class="attendance-hero-icon">◷</div></section>'+
 '<section class="panel attendance-filter-panel"><form id="attendanceFilter" class="attendance-filter"><label class="field">From<input type="date" name="start" value="'+esc(start)+'" required></label><label class="field">To<input type="date" name="end" value="'+esc(end)+'" required></label><button class="gold-button" type="submit">Apply filter</button><button class="secondary-button" type="button" id="resetAttendanceFilter">Last 7 days</button></form></section>'+
 '<div class="stats attendance-stats">'+stat('Attendance records',attendanceRows.length)+stat('Staff members',names.length)+stat('Complete shifts',complete.length)+stat('Missing checkout',missing.length)+stat('Recorded work time',attendanceHours(totalMinutes))+'</div>'+
 '<section class="panel"><div class="attendance-section-head"><div><h2>Attendance records</h2><p class="help">'+esc(start)+' — '+esc(end)+' · '+attendanceRows.length+' records</p></div><div class="attendance-actions"><button class="secondary-button" id="exportAttendanceCsv" type="button">Download CSV</button><button class="secondary-button" id="printAttendance" type="button">Print report</button></div></div>'+
 (statusLine?'<div class="attendance-status-list">'+statusLine+'</div>':'')+
 (rows?'<div class="table-wrap"><table class="data-table attendance-table"><thead><tr><th>Staff</th><th>Date</th><th>Check in</th><th>Check out</th><th>Work time</th><th>Status</th></tr></thead><tbody>'+rows+'</tbody></table></div>':'<div class="empty">No attendance records in this date range.</div>')+
 '<p class="attendance-footnote">Work time is calculated only when both check-in and check-out are present. Overnight shifts are supported. Missing values are not estimated. Select a Staff photo/name to open their individual report for this date filter.</p></section>'+personHtml;
}
function exportAttendanceCsv(){
 const head=['staff_name','attendance_date','check_in','check_out','work_time_minutes','status'];
 const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';
 const lines=[head.join(',')].concat(attendanceRows.map(x=>[x.staff_name,x.attendance_date,x.check_in,x.check_out,attendanceDuration(x.check_in,x.check_out),x.status].map(quote).join(',')));
 const blob=new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download='staff-attendance-'+(attendanceStart||'last-7-days')+'-'+(attendanceEnd||attendanceDateValue(new Date()))+'.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);
}
function exportIndividualAttendanceCsv(){
 if(!selectedAttendanceStaff)return;
 const rows=attendanceRows.filter(x=>(x.staff_name||'Unknown staff')===selectedAttendanceStaff);
 const head=['staff_name','attendance_date','check_in','check_out','work_time_minutes','status'];
 const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';
 const lines=[head.join(',')].concat(rows.map(x=>[x.staff_name,x.attendance_date,x.check_in,x.check_out,attendanceDuration(x.check_in,x.check_out),x.status].map(quote).join(',')));
 const safe=selectedAttendanceStaff.toLowerCase().replace(/[^a-z0-9-]+/g,'-').replace(/^-|-$/g,'')||'staff';
 const blob=new Blob(['\\uFEFF'+lines.join('\\r\\n')],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download='attendance-'+safe+'-'+(attendanceStart||'last-7-days')+'-'+(attendanceEnd||attendanceDateValue(new Date()))+'.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);
}


function qrMenuPage(){
 return '<section class="panel"><h2>Upload QR Menu page images</h2><p class="help">Upload complete menu-page images. The public QR Menu displays only these images, not dish text or prices from the database.</p><form id="qrMenuUploadForm" class="admin-form"><label class="field">Choose image (JPG, PNG or WebP; max 12 MB)<input id="qrMenuImageFile" type="file" accept="image/jpeg,image/png,image/webp" required></label><img id="qrMenuPreview" class="crud-image-preview" alt="QR Menu preview" hidden><button class="gold-button" type="submit">Upload to QR Menu</button><p id="qrMenuStatus" class="message" aria-live="polite"></p></form></section><section class="panel"><h2>Saved QR Menu images</h2><div id="qrMenuImages"><p class="help">Loading…</p></div></section><section class="panel"><h2>Restaurant QR Code</h2><p class="help">All tables open the same QR Menu.</p><img style="width:220px;max-width:100%;background:#fff;padding:10px;border-radius:12px" src="https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=https%3A%2F%2Fnababiristorante.vercel.app%2Fqr-menu.html" alt="QR Menu"><p><a href="https://nababiristorante.vercel.app/qr-menu.html" target="_blank" rel="noopener">Open QR Menu</a></p></section>';
}
async function loadQrMenuImagesV2(){
 const host=$('#qrMenuImages');if(!host)return;
 const r=await db.from('qr_menu_images').select('id,image_url,is_active,sort_order').order('sort_order',{ascending:true}).order('created_at',{ascending:true});
 if(r.error)throw r.error;
 const rows=r.data||[];
 host.innerHTML=rows.length?'<div class="record-list">'+rows.map((x,i)=>'<article class="record-row" style="display:flex;align-items:center;gap:12px;flex-wrap:wrap"><img src="'+esc(x.image_url)+'" alt="QR Menu page '+(i+1)+'" style="width:90px;height:110px;object-fit:contain;background:#fff;border-radius:8px"><div style="flex:1;min-width:130px"><b>Menu page '+(i+1)+'</b><p class="help">'+(x.is_active?'Visible on QR Menu':'Hidden from QR Menu')+' · Order '+esc(x.sort_order)+'</p></div><div class="form-actions"><button type="button" class="small-button" data-qr-action="up" data-id="'+esc(x.id)+'" '+(i===0?'disabled':'')+'>↑</button><button type="button" class="small-button" data-qr-action="down" data-id="'+esc(x.id)+'" '+(i===rows.length-1?'disabled':'')+'>↓</button><button type="button" class="small-button" data-qr-action="toggle" data-active="'+String(x.is_active)+'" data-id="'+esc(x.id)+'">'+(x.is_active?'Hide':'Show')+'</button><button type="button" class="small-button danger-button" data-qr-action="delete" data-id="'+esc(x.id)+'">Delete</button></div></article>').join('')+'</div>':'<div class="empty">No QR Menu images uploaded yet.</div>';
}
async function uploadQrMenuImageV2(e){
 e.preventDefault();const form=e.target,input=$('#qrMenuImageFile'),status=$('#qrMenuStatus'),button=form.querySelector('[type="submit"]'),file=input.files&&input.files[0];
 if(!file){status.textContent='Choose an image first.';return}
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12*1024*1024){status.textContent='Use JPG, PNG or WebP, maximum 12 MB.';return}
 button.disabled=true;status.textContent='Uploading…';
 try{
  const publicUrl=await uploadImage(file,'qr-menu',12*1024*1024);
  const last=await db.from('qr_menu_images').select('sort_order').order('sort_order',{ascending:false}).limit(1);if(last.error)throw last.error;
  const ins=await db.from('qr_menu_images').insert({image_url:publicUrl,is_active:true,sort_order:Number(last.data?.[0]?.sort_order||0)+1});if(ins.error)throw ins.error;
  input.value='';$('#qrMenuPreview').hidden=true;$('#qrMenuPreview').removeAttribute('src');status.textContent='Image uploaded successfully.';await loadQrMenuImagesV2();
 }catch(err){status.textContent=err.message||'Upload failed.'}finally{button.disabled=false}
}
async function handleQrMenuAction(button){
 const id=button.dataset.id,action=button.dataset.qrAction;button.disabled=true;
 try{
  if(action==='toggle'){const r=await db.from('qr_menu_images').update({is_active:button.dataset.active!=='true'}).eq('id',id);if(r.error)throw r.error}
  else if(action==='delete'){if(!confirm('Delete this QR Menu image?'))return;const r=await db.from('qr_menu_images').delete().eq('id',id);if(r.error)throw r.error}
  else if(action==='up'||action==='down'){
   const r=await db.from('qr_menu_images').select('id,sort_order').order('sort_order',{ascending:true}).order('created_at',{ascending:true});if(r.error)throw r.error;
   const rows=r.data||[],pos=rows.findIndex(x=>String(x.id)===String(id)),other=rows[pos+(action==='up'?-1:1)];
   if(pos>=0&&other){const here=rows[pos],a=await db.from('qr_menu_images').update({sort_order:other.sort_order}).eq('id',here.id);if(a.error)throw a.error;const b=await db.from('qr_menu_images').update({sort_order:here.sort_order}).eq('id',other.id);if(b.error)throw b.error}
  }
  await loadQrMenuImagesV2();
 }catch(err){alert(err.message||'QR Menu action failed.')}finally{button.disabled=false}
}


async function galleryPage(){
 const r=await db.from('gallery_items').select('*').order('sort_order',{ascending:true}).order('created_at',{ascending:true});
 if(r.error)throw r.error;
 const rows=r.data||[];
 return '<section class="panel gallery-upload-panel"><h2>Upload Gallery image</h2><p class="help">JPG, PNG or WebP · maximum 8 MB. New images are visible on the public website by default.</p><form id="galleryUploadForm" class="admin-form"><label class="field">Image file<input id="galleryImageFile" name="image" type="file" accept="image/jpeg,image/png,image/webp" required></label><img id="galleryPreview" class="gallery-preview" alt="Gallery image preview" hidden><label class="field">Title<input name="title" type="text" maxlength="150" placeholder="Image title"></label><label class="field">Description<textarea name="description" maxlength="1000" placeholder="Optional description"></textarea></label><button class="gold-button" type="submit">Upload image</button><p id="galleryStatus" class="message" role="status" aria-live="polite"></p></form></section><section class="panel"><div class="gallery-section-heading"><div><h2>Saved Gallery images</h2><p class="help">Use the arrows to change display order. Hidden images remain saved and can be shown again.</p></div><span class="gallery-count">'+rows.length+' images</span></div>'+(rows.length?'<div class="gallery-grid">'+rows.map((x,i)=>'<article class="gallery-card"><img class="gallery-card-image" src="'+esc(x.image_url)+'" alt="'+esc(x.title||'Gallery image '+(i+1))+'" loading="lazy"><div class="gallery-card-body"><b>'+esc(x.title||'Untitled image')+'</b>'+(x.description?'<p>'+esc(x.description)+'</p>':'')+'<small>'+(x.is_active?'Visible on website':'Hidden from website')+' · Order '+esc(x.sort_order??i+1)+'</small><div class="gallery-card-actions"><button type="button" class="small-button" data-gallery-action="up" data-id="'+esc(x.id)+'" '+(i===0?'disabled':'')+' aria-label="Move image up">↑</button><button type="button" class="small-button" data-gallery-action="down" data-id="'+esc(x.id)+'" '+(i===rows.length-1?'disabled':'')+' aria-label="Move image down">↓</button><button type="button" class="small-button" data-gallery-action="toggle" data-active="'+String(x.is_active===true)+'" data-id="'+esc(x.id)+'">'+(x.is_active?'Hide':'Show')+'</button><button type="button" class="small-button danger-button" data-gallery-action="delete" data-id="'+esc(x.id)+'">Delete</button></div></div></article>').join('')+'</div>':'<div class="empty">No Gallery images uploaded yet.</div>')+'</section>';
}
async function uploadGalleryImage(e){
 e.preventDefault();const form=e.target,fd=new FormData(form),file=fd.get('image'),status=$('#galleryStatus'),button=form.querySelector('[type="submit"]');
 if(!file||!file.size){status.textContent='Choose an image first.';return}
 button.disabled=true;status.textContent='Uploading…';
 try{
  const image_url=await uploadImage(file,'gallery',8*1024*1024);
  const last=await db.from('gallery_items').select('sort_order').order('sort_order',{ascending:false}).limit(1);if(last.error)throw last.error;
  const payload={image_url,title:String(fd.get('title')||'').trim()||null,description:String(fd.get('description')||'').trim()||null,sort_order:Number(last.data?.[0]?.sort_order||0)+1,is_active:true};
  const ins=await db.from('gallery_items').insert(payload);if(ins.error)throw ins.error;
  await recordStaffActivity('Created','Module: Gallery — image uploaded');
  await render('gallery');
 }catch(err){status.textContent=err.message||'Gallery upload failed.'}finally{button.disabled=false}
}
async function handleGalleryAction(button){
 const id=button.dataset.id,action=button.dataset.galleryAction;button.disabled=true;
 try{
  if(action==='toggle'){const r=await db.from('gallery_items').update({is_active:button.dataset.active!=='true'}).eq('id',id);if(r.error)throw r.error;await recordStaffActivity('Updated','Module: Gallery — visibility changed')}
  else if(action==='delete'){if(!confirm('Delete this Gallery image record? This cannot be undone.'))return;const r=await db.from('gallery_items').delete().eq('id',id);if(r.error)throw r.error;await recordStaffActivity('Deleted','Module: Gallery — image record deleted')}
  else if(action==='up'||action==='down'){
   const r=await db.from('gallery_items').select('id,sort_order').order('sort_order',{ascending:true}).order('created_at',{ascending:true});if(r.error)throw r.error;
   const rows=r.data||[],pos=rows.findIndex(x=>String(x.id)===String(id)),next=pos+(action==='up'?-1:1);
   if(pos>=0&&next>=0&&next<rows.length){
    const reordered=rows.slice(),[moved]=reordered.splice(pos,1);reordered.splice(next,0,moved);
    for(let i=0;i<reordered.length;i++){const u=await db.from('gallery_items').update({sort_order:i+1}).eq('id',reordered[i].id);if(u.error)throw u.error}
   }
  }
  await render('gallery');
 }catch(err){alert(err.message||'Gallery action failed.')}finally{button.disabled=false}
}

async function crudPage(id){
 const cfg=crudConfigs[id],r=await db.from(cfg.table).select('*').limit(150);if(r.error)throw r.error;
 const rows=r.data||[],key=cfg.key||'id',canEdit=cfg.mode!=='readonly',canCreate=cfg.mode!=='update'&&cfg.mode!=='singleton'&&!cfg.noCreate,canDelete=cfg.mode!=='update'&&cfg.mode!=='singleton'&&id!=='about';
 const showForm=canEdit&&(canCreate||!!editingRecord||(cfg.mode==='singleton'&&rows.length>0));const form=showForm?'<section class="panel"><h2 id="crudHeading">'+(editingRecord?'Edit record':cfg.mode==='singleton'?'Edit settings':'Add record')+'</h2><form id="crudForm" class="admin-form" data-module="'+id+'"><input type="hidden" name="_key" value="'+esc(editingRecord||'')+'">'+cfg.fields.map(f=>inputFor(f)).join('')+'<div class="form-actions"><button class="gold-button" type="submit">'+t('save')+'</button><button class="secondary-button" id="cancelCrud" type="button">'+t('cancel')+'</button></div><p id="crudStatus" class="message"></p></form></section>':'';
 let table;
 if(id==='news'){
  table=rows.length?'<div class="table-wrap"><table class="data-table news-admin-table"><thead><tr><th>Title</th><th>Saved media</th><th>Body</th><th>Starts</th><th>Ends</th><th>Status</th><th>Actions</th></tr></thead><tbody>'+rows.map(row=>'<tr><td><b>'+displayValue(row.title)+'</b></td><td>'+breakingNewsMediaCell(row)+'</td><td class="news-body-cell">'+displayValue(row.body)+'</td><td>'+displayValue(row.starts_at)+'</td><td>'+displayValue(row.ends_at)+'</td><td><span class="news-active-state '+(row.is_active?'active':'inactive')+'">'+(row.is_active?'Active':'Inactive')+'</span></td><td><button class="small-button" data-edit-record="'+esc(row[key])+'" data-module="'+id+'">Edit</button></td></tr>').join('')+'</tbody></table></div>':'<div class="empty">'+t('empty')+'</div>';
 }else{
  const cols=rows.length?Object.keys(rows[0]).filter(k=>!['visitor_token_hash'].includes(k)).slice(0,7):[];
  table=rows.length?'<div class="table-wrap"><table class="data-table"><thead><tr>'+cols.map(k=>'<th>'+esc(k)+'</th>').join('')+'<th>Actions</th></tr></thead><tbody>'+rows.map(row=>'<tr>'+cols.map(k=>'<td>'+displayValue(row[k])+'</td>').join('')+'<td>'+(canEdit?'<button class="small-button" data-edit-record="'+esc(row[key])+'" data-module="'+id+'">Edit</button> ':'')+(canDelete?'<button class="small-button danger-button" data-delete-record="'+esc(row[key])+'" data-module="'+id+'">Delete</button>':'')+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty">'+t('empty')+'</div>';
 }
 const note=id==='about'?'Only edit keys already used by the website. Adding a new key does not automatically connect it to the public About section.':id==='discount'?'This is a single settings row; saving updates the existing row only.':id==='bookings'?'Booking records are preserved; this panel edits their status and staff notes without deleting reservations.':id==='news'?'Saved image thumbnails and YouTube video previews are shown below. Existing news records and media are not changed by this view.':'Changes are subject to the existing Supabase Row Level Security policies.';
 return '<section class="panel"><p class="help">'+note+'</p></section>'+form+'<section class="panel"><h2>'+cfg.title+'</h2>'+table+'</section>';
}
let editingRecord=null,attendanceRows=[],attendanceStart='',attendanceEnd='',selectedAttendanceStaff='';
async function saveCrud(e){
 e.preventDefault();const form=e.target,id=form.dataset.module,cfg=crudConfigs[id],fd=new FormData(form),payload={};
 for(const f of cfg.fields){const [name,,type]=f;let value;if(type==='boolean')value=form.elements[name].checked;else if(type==='image'){const file=form.elements[name].files?.[0];value=file?await uploadImage(file,id==='gallery'?'gallery':id==='qr_menu_images'?'qr-menu':id==='news'?'news':'secret-coupon'):(fd.get(name+'_existing')||null);if(f[3]===true&&!value)throw new Error(f[1]+' is required.')}else value=fd.get(name);if(type==='number')value=value===''?null:Number(value);if(type==='datetime')value=value?new Date(value).toISOString():null;if(typeof value==='string')value=value.trim();if(value===''&&!f[3])value=null;if(f[3]===true&&(value===null||value===''))throw new Error(f[1]+' is required.');payload[name]=value}
 const key=cfg.key||(cfg.mode==='settings'?'setting_key':'id'),editing=String(fd.get('_key')||'');
 let q;
 if(cfg.mode==='singleton'){payload.id=true;q=db.from(cfg.table).update(payload).eq('id',true)}
 else if(cfg.mode==='settings'){if(editing){q=db.from(cfg.table).update({setting_value:payload.setting_value}).eq('setting_key',editing)}else{q=db.from(cfg.table).insert(payload)}}
 else if(editing){q=db.from(cfg.table).update(payload).eq(key,editing)}
 else{q=db.from(cfg.table).insert(payload)}
 const result=await q;if(result.error)throw result.error;await recordStaffActivity(editing?'Updated':'Created','Module: '+(cfg.title||id)+' — '+(payload.name||payload.title||payload.code||payload.platform||'Record saved'));editingRecord=null;await render(id);
}
async function editCrudRecord(id,key){
 const cfg=crudConfigs[id],column=cfg.key||(cfg.mode==='settings'?'setting_key':'id'),r=await db.from(cfg.table).select('*').eq(column,key).single();if(r.error)throw r.error;
 editingRecord=String(key);await render(id);
 const form=$('#crudForm');if(!form)return;
 form.elements._key.value=String(key);
 for(const [name,,type] of cfg.fields){const el=form.elements[name];if(!el)continue;const value=r.data[name];if(type==='boolean')el.checked=value===true;else if(type==='image'){form.elements[name+'_existing'].value=value||'';const preview=el.parentElement.querySelector('img');if(value&&!preview)el.insertAdjacentHTML('afterend','<img class="crud-image-preview" src="'+esc(value)+'" alt="Current image">');else if(value&&preview)preview.src=value;}else if(type==='datetime'&&value){const d=new Date(value);el.value=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}else el.value=value??''}
 $('#crudHeading').textContent='Edit record';
}

async function loadStaffAnnouncements(){const host=$('#staffAnnouncementList');if(!host)return;const r=await db.from('staff_announcements').select('id,title,message,starts_at,ends_at,is_active').order('starts_at',{ascending:false}).limit(50);if(r.error)throw r.error;host.innerHTML=(r.data||[]).map(x=>'<article class="record-row"><div><b>'+esc(x.title)+'</b><p>'+esc(x.message)+'</p><small>'+esc(x.starts_at||'')+' – '+esc(x.ends_at||'')+'</small></div><button class="small-button" data-disable-announcement="'+esc(x.id)+'">'+(x.is_active?'Disable':'Disabled')+'</button></article>').join('')||'<p class="empty">No announcements.</p>'}
async function createAttendanceStaff(e){e.preventDefault();if(role!=='admin')throw new Error('Admin only.');const form=e.target,fd=new FormData(form),status=$('#attendanceStaffStatus'),file=fd.get('photo'),pin=String(fd.get('pin')||'');if(!/^[0-9]{4}$/.test(pin))throw new Error('PIN must contain exactly four digits.');if(!file||!file.size)throw new Error('Select a staff photo.');if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw new Error('Use JPG, PNG or WebP up to 8 MB.');let path=null;try{const ext=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg',bucket=cfg.STORAGE_BUCKET||'nababi-media';const up=await db.storage.from(bucket).upload('staff/'+Date.now()+'-'+Math.random().toString(36).slice(2)+'.'+ext,file,{cacheControl:'3600',upsert:false,contentType:file.type});if(up.error)throw up.error;path=up.data.path;const url=db.storage.from(bucket).getPublicUrl(path).data.publicUrl;const r=await db.rpc('admin_create_staff_pin_account',{p_full_name:String(fd.get('full_name')||'').trim(),p_photo_url:url,p_pin:pin});if(r.error)throw r.error;if(!r.data?.ok)throw new Error(r.data?.message||'Staff account creation failed.');form.reset();status.textContent=r.data.message||'Attendance account created.';await render('staff')}catch(err){if(path)await db.storage.from(cfg.STORAGE_BUCKET||'nababi-media').remove([path]);status.textContent=err.message;throw err}}
async function publishStaffAnnouncement(e){e.preventDefault();if(role!=='admin')throw new Error('Admin only.');const fd=new FormData(e.target),title=String(fd.get('title')||'').trim(),message=String(fd.get('message')||'').trim();if(!title||!message)throw new Error('Title and message are required.');const r=await db.from('staff_announcements').insert({title,message,starts_at:fd.get('starts_at')?new Date(fd.get('starts_at')).toISOString():new Date().toISOString(),ends_at:fd.get('ends_at')?new Date(fd.get('ends_at')).toISOString():null,is_active:true});if(r.error)throw r.error;e.target.reset();await loadStaffAnnouncements()}

async function secretPage(){const [history]=await Promise.all([db.from('coupon_redemptions').select('coupon_code,discount_percent,redeemed_by_name,redeemed_at').order('redeemed_at',{ascending:false}).limit(100)]);if(history.error)throw history.error;return '<section class="panel secret-coupon-panel"><div class="secret-coupon-heading"><div><p class="eyebrow">NABABI · CUSTOMER REWARDS</p><h2>🎁 Secret Coupon Box</h2><p class="help">Enter the code shown by the customer. Each valid coupon can be redeemed only once.</p></div><span class="secret-coupon-mark" aria-hidden="true">♛</span></div><form id="redeemSecretForm" class="admin-form"><label class="field">Customer coupon code<input name="code" inputmode="numeric" autocomplete="off" pattern="[0-9]{5,9}" minlength="5" maxlength="9" placeholder="Enter 5–9 digit code" required></label><button class="gold-button" type="submit">Verify &amp; Redeem</button><p id="redeemSecretStatus" class="message secret-coupon-result" role="status" aria-live="polite"></p></form></section>'+(role==='admin'?'<section class="panel"><h2>Generate customer coupon</h2><button id="generateSecretCoupon" class="gold-button" type="button">Generate coupon</button><div id="generatedCoupon" class="message"></div></section>':'')+'<section class="panel"><h2>Redemption history</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Coupon</th><th>Discount</th><th>Collected by</th><th>Date</th></tr></thead><tbody>'+(history.data||[]).map(x=>'<tr><td>'+esc(x.coupon_code)+'</td><td>'+esc(x.discount_percent)+'%</td><td>'+esc(x.redeemed_by_name||'Staff')+'</td><td>'+esc(x.redeemed_at?new Date(x.redeemed_at).toLocaleString():'')+'</td></tr>').join('')+'</tbody></table></div></section>'}
function launchSecretFireworks(){document.querySelectorAll('.secret-fireworks').forEach(x=>x.remove());const layer=document.createElement('div');layer.className='secret-fireworks';layer.setAttribute('aria-hidden','true');for(let burst=0;burst<7;burst++){const group=document.createElement('div');group.className='secret-firework-burst';group.style.left=(10+burst*13)+'%';group.style.top=(18+(burst%3)*24)+'%';group.style.setProperty('--burst-delay',(burst*110)+'ms');for(let i=0;i<24;i++){const spark=document.createElement('i');spark.style.setProperty('--angle',(i*15)+'deg');spark.style.setProperty('--distance',(105+(i%5)*27)+'px');spark.style.setProperty('--hue',String((i*19+burst*53)%360));group.appendChild(spark)}layer.appendChild(group)}document.body.appendChild(layer);window.setTimeout(()=>layer.remove(),3200)}
function showSecretResult(state,message,discount){const success=state==='success';$('#pageTitle').textContent=success?'Coupon redeemed':'Coupon not accepted';$('#content').innerHTML='<section class="secret-result-screen '+(success?'is-success':'is-error')+'" role="status" aria-live="assertive"><div class="secret-result-card"><div class="secret-result-icon" aria-hidden="true">'+(success?'🎉':'✕')+'</div><p class="eyebrow">'+(success?'NABABI · CUSTOMER REWARDS':'NABABI · COUPON VERIFICATION')+'</p><h2>'+(success?'Congratulations!':'Coupon not valid')+'</h2><p class="secret-result-message">'+esc(message)+'</p>'+(success?'<div class="secret-result-discount">'+esc(discount||'')+'% <span>DISCOUNT</span></div>':'<p class="secret-result-hint">Please check the customer code and try again.</p>')+'<button class="gold-button" type="button" data-module="secret">'+(success?'Back to Secret Coupon Box':'Try another code')+'</button></div></section>';if(success)launchSecretFireworks();}
async function redeemSecretCoupon(e){e.preventDefault();const form=e.target,code=String(new FormData(form).get('code')||'').trim(),button=form.querySelector('[type="submit"]');button.disabled=true;try{if(!/^[0-9]{5,9}$/.test(code))throw new Error('Invalid code. Enter the 5–9 digit customer code.');const r=await db.rpc('redeem_nababi_coupon',{p_code:code});if(r.error)throw r.error;if(!r.data?.success)throw new Error(r.data?.message||'Invalid or already redeemed coupon.');await recordStaffActivity('Redeemed','Module: Secret Coupon Box — '+code);showSecretResult('success','Your coupon has been verified and redeemed successfully.',r.data.discount_percent||'');}catch(err){showSecretResult('error',err.message||'Invalid coupon code. Please check and try again.')}finally{button.disabled=false}}
async function generateSecretCoupon(){if(role!=='admin')throw new Error('Admin only.');const out=$('#generatedCoupon'),r=await db.rpc('generate_nababi_coupon');if(r.error)throw r.error;if(!r.data?.success)throw new Error(r.data?.message||'Coupon generation failed.');out.textContent='Generated code: '+r.data.code+' · '+r.data.discount_percent+'% discount';}
