async function saveDiscountOffer(e){e.preventDefault();if(role!=='admin')throw new Error('Admin only.');const fd=new FormData(e.target),start=fd.get('starts_at'),end=fd.get('ends_at'),max=fd.get('max_coupons');if(!start||!end||new Date(end)<=new Date(start))throw new Error('Check the offer start and end dates.');if(max&&(!Number.isInteger(Number(max))||Number(max)<1))throw new Error('Maximum coupons must be a positive whole number.');const r=await db.rpc('save_nababi_coupon_offer',{p_discount_percent:Number(fd.get('discount_percent')),p_starts_at:new Date(start).toISOString(),p_ends_at:new Date(end).toISOString(),p_is_enabled:$('#discountOfferForm').elements.is_enabled.checked,p_max_coupons:max?Number(max):null});if(r.error)throw r.error;if(!r.data?.success)throw new Error(r.data?.message||'Offer save failed.');await render('discount')}
async function activityPage(){
 const [{data:logs,error:logError},{data:staff,error:staffError}]=await Promise.all([
  db.from('staff_activity_logs').select('*').limit(200),
  db.from('staff').select('id,auth_user_id,full_name,photo_url')
 ]);
 if(logError)throw logError;
 if(staffError)throw staffError;
 const people=staff||[];
 const byId=new Map(people.map(p=>[String(p.id),p]));
 const byAuth=new Map(people.filter(p=>p.auth_user_id).map(p=>[String(p.auth_user_id),p]));
 const byName=new Map(people.map(p=>[String(p.full_name||'').trim().toLocaleLowerCase(),p]));
 const rows=(logs||[]).slice().sort((a,b)=>new Date(b.created_at||b.performed_at||b.timestamp||0)-new Date(a.created_at||a.performed_at||a.timestamp||0));
 const value=(row,keys)=>{for(const key of keys){const v=row[key];if(v!==undefined&&v!==null&&v!=='')return typeof v==='object'?JSON.stringify(v):String(v)}return ''};
 const escAttr=v=>esc(v).replace(/\`/g,'&#96;');
 const avatar=(person,name)=>person?.photo_url?'<img src="'+escAttr(person.photo_url)+'" alt="'+escAttr(name)+'" style="width:48px;height:48px;object-fit:cover;border-radius:50%;flex:0 0 auto">':'<div aria-label="Staff photo unavailable" style="width:48px;height:48px;border-radius:50%;background:#e8dfc9;color:#334;display:grid;place-items:center;font-size:20px;flex:0 0 auto">♟</div>';
 return '<section class="panel"><h2>'+t('activity')+'</h2><p class="help">Recent staff actions. Staff ID is kept internal and is not displayed.</p>'+
 (rows.length?'<div class="table-wrap"><table class="data-table"><thead><tr><th>Staff</th><th>Activity</th><th>Module</th><th>Date &amp; Time</th></tr></thead><tbody>'+
 rows.map(row=>{
  const person=byId.get(String(row.staff_id||row.staffId||''))||byAuth.get(String(row.auth_user_id||row.user_id||''))||byName.get(String(row.staff_name||row.full_name||row.actor_name||'').trim().toLocaleLowerCase());
  const name=person?.full_name||value(row,['staff_name','full_name','actor_name','user_name'])||'Staff';
  const action=value(row,['action','activity','event','description','action_name'])||'Activity recorded';
  const detail=value(row,['details']);const moduleMatch=detail.match(/Module:\s*([^—\n]+)/i);const module=moduleMatch?moduleMatch[1].trim():'—';
  const stamp=value(row,['created_at','performed_at','timestamp','activity_at','logged_at']);
  const date=stamp&&!Number.isNaN(new Date(stamp).getTime())?new Date(stamp).toLocaleString():(stamp||'—');
  return '<tr><td><span style="display:inline-flex;align-items:center;gap:10px">'+avatar(person,name)+'<b>'+esc(name)+'</b></span></td><td>'+esc(action)+'</td><td>'+esc(module)+'</td><td>'+esc(date)+'</td></tr>';
 }).join('')+'</tbody></table></div>':'<div class="empty">'+t('empty')+'</div>')+'</section>';
}
async function hoursPage(){const r=await db.from('opening_hours').select('id,day_of_week,day_name,is_closed,opens_at,closes_at').order('day_of_week');if(r.error)throw r.error;return '<section class="panel"><h2>Opening hours</h2><form id="hoursForm">'+(r.data||[]).map(x=>'<div class="record-row"><b>'+esc(x.day_name)+'</b><label class="check-label"><input type="checkbox" name="closed_'+esc(x.id)+'" '+(x.is_closed?'checked':'')+'> Closed</label><label class="field">Opens<input type="time" name="open_'+esc(x.id)+'" value="'+esc(x.opens_at?String(x.opens_at).slice(0,5):'')+'"></label><label class="field">Closes<input type="time" name="close_'+esc(x.id)+'" value="'+esc(x.closes_at?String(x.closes_at).slice(0,5):'')+'"></label></div>').join('')+'<button class="gold-button" type="submit">Save opening hours</button><p id="hoursStatus" class="message"></p></form></section>'}
async function saveHours(e){e.preventDefault();const form=e.target,status=$('#hoursStatus'),ids=[...form.querySelectorAll('[name^="closed_"]')].map(x=>x.name.slice(7));for(const id of ids){const closed=form.elements['closed_'+id].checked,open=form.elements['open_'+id].value,close=form.elements['close_'+id].value;if(!closed&&(!open||!close||open>=close))throw new Error('Enter valid opening and closing times or mark the day closed.');const r=await db.from('opening_hours').update({is_closed:closed,opens_at:closed?null:open,closes_at:closed?null:close,updated_at:new Date().toISOString()}).eq('id',id).select('id').maybeSingle();if(r.error)throw r.error;if(!r.data)throw new Error('No opening-hours row was updated. Check Supabase RLS.')}status.textContent='Opening hours saved.'}

function staffQrCodePage(){const currentUrl=new URL('/staff-qr.html',location.origin).href;return '<section class="attendance-hero"><div><p class="eyebrow">NABABI RISTORANTE</p><h2>Staff Attendance QR</h2><p>Edit the QR destination, preview it and download a PNG copy.</p></div><div class="attendance-hero-icon">▣</div></section><section class="panel staff-qr-manager"><h2>QR Code Editor</h2><label class="field" for="staffQrValue">QR destination URL<input id="staffQrValue" type="url" value="'+esc(currentUrl)+'" autocomplete="url" spellcheck="false"></label><div class="staff-qr-actions"><button id="resetStaffQr" class="secondary-button" type="button">Use current attendance link</button><button id="downloadStaffQr" class="gold-button" type="button">Download QR · PNG</button></div><div id="staffQrPreview" class="staff-qr-preview" aria-label="QR code preview"></div><p id="staffQrStatus" class="attendance-footnote" role="status" aria-live="polite">Default link: '+esc(currentUrl)+'</p><p class="attendance-footnote">Important: changing this URL changes only the QR image you download. To keep Staff Check-in/Check-out working, use the current attendance link shown above. This editor does not change attendance records or database settings.</p></section>'}
function initStaffQrCode(){const input=$('#staffQrValue'),preview=$('#staffQrPreview'),status=$('#staffQrStatus');if(!input||!preview||!status)return;let qr=null;const draw=()=>{preview.replaceChildren();const value=input.value.trim();if(!value){status.textContent='Enter a URL to create the QR code.';qr=null;return}let url;try{url=new URL(value);if(!['https:','http:'].includes(url.protocol))throw new Error('Only HTTP or HTTPS links are supported.')}catch(e){status.textContent=e.message==='Only HTTP or HTTPS links are supported.'?e.message:'Enter a valid URL.';qr=null;return}if(typeof QRCode!=='function'){status.textContent='QR generator could not be loaded. Check your internet connection and reload this page.';qr=null;return}qr=new QRCode(preview,{text:url.href,width:280,height:280,colorDark:'#102d24',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.H});status.textContent='QR preview ready · '+url.href};input.addEventListener('input',draw);$('#resetStaffQr').addEventListener('click',()=>{input.value=new URL('/staff-qr.html',location.origin).href;draw()});$('#downloadStaffQr').addEventListener('click',()=>{if(!qr){draw();if(!qr)return}const canvas=preview.querySelector('canvas');const image=preview.querySelector('img');let dataUrl='';if(canvas){try{dataUrl=canvas.toDataURL('image/png')}catch(e){status.textContent='Could not export the QR image. Please reload and try again.';return}}else if(image&&image.src.startsWith('data:image/'))dataUrl=image.src;if(!dataUrl){status.textContent='QR image is not ready yet. Please try again.';return}const link=document.createElement('a');link.href=dataUrl;link.download='nababi-staff-attendance-qr.png';document.body.appendChild(link);link.click();link.remove();status.textContent='PNG download started.'});draw()}


